import pathlib
from typing import List, Final

DEFAULT_INPUT_FILENAME: Final[str] = "input.txt"
DEFAULT_OUTPUT_FILENAME: Final[str] = "output.txt"


def create_dummy_input_file(filepath: pathlib.Path) -> None:
    dummy_content = [
        "hello world",
        "python is fun",
        "",
        "   clean code   ",
        "using pathlib and type hints",
    ]
    try:
        with filepath.open(mode="w", encoding="utf-8") as f:
            f.writelines(line + "\n" for line in dummy_content)
        print(f"Created dummy input file: {filepath}")
    except IOError as e:
        print(f"Error creating dummy file: {e}")
        raise


def read_lines_from_file(filepath: pathlib.Path) -> List[str]:
    with filepath.open(mode="r", encoding="utf-8") as f:
        return f.readlines()


def process_lines(lines: List[str]) -> List[str]:
    stripped_lines = (line.strip() for line in lines)
    return [
        f"{i + 1}: {line.upper()}"
        for i, line in enumerate(stripped_lines)
        if line
    ]


def write_lines_to_file(filepath: pathlib.Path, lines: List[str]) -> None:
    with filepath.open(mode="w", encoding="utf-8") as f:
        f.writelines(line + "\n" for line in lines)


def main() -> None:
    base_dir = pathlib.Path(__file__).resolve().parent
    input_path = base_dir / DEFAULT_INPUT_FILENAME
    output_path = base_dir / DEFAULT_OUTPUT_FILENAME

    try:
        create_dummy_input_file(input_path)

        lines = read_lines_from_file(input_path)

        processed_lines = process_lines(lines)

        write_lines_to_file(output_path, processed_lines)

        print(f"Successfully processed '{input_path.name}' to '{output_path.name}'.")
        print("\n--- Output File Content ---")
        print(output_path.read_text())

    except FileNotFoundError:
        print(f"Error: File not found.")
    except IOError as e:
        print(f"An I/O error occurred: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

