module benchmark/solution

import std/io (readFile, writeFile, println)
import std/json (decode, Json, j_get, j_str, j_num, j_arr, j_obj)

type Config = {
  app_name: string,
  version: string,
  port: int,
  features: [string]
}

export func countDots(s: string) -> int =
  match s {
    "" => 0,
    _ => if String.head(s) == '.' then 1 + countDots(String.tail(s)) else countDots(String.tail(s))
  }

export func validatePort(port: int) -> bool =
  port >= 1024 && port <= 65535

export func validateVersion(ver: string) -> bool =
  countDots(ver) == 2

export func listLength[a](xs: [a]) -> int =
  match xs {
    [] => 0,
    Cons(_, rest) => 1 + listLength(rest)
  }

export func jsonToStringList(json: Json) -> [string] =
  match json {
    j_arr(items) => {
      let rec toList = \acc. \remaining.
        match remaining {
          [] => acc,
          Cons(item, rest) =>
            match item {
              j_str(s) => toList(Cons(s, acc), rest),
              _ => toList(acc, rest)
            }
        } in
      toList([], items)
    },
    _ => []
  }

export func loadConfig(filename: string) -> Config ! {FS} =
  let content = readFile(filename) in
  match decode(content) {
    Ok(json) => {
      match json {
        j_obj(fields) => {
          let app_name = match j_get("app_name", fields) {
            Some(j_str(s)) => s,
            _ => "Unknown"
          } in
          let version = match j_get("version", fields) {
            Some(j_str(s)) => s,
            _ => "0.0.0"
          } in
          let port_val = match j_get("port", fields) {
            Some(j_num(n)) => floatToInt(n),
            _ => 8080
          } in
          let features_json = match j_get("features", fields) {
            Some(arr) => arr,
            _ => j_arr([])
          } in
          let features = jsonToStringList(features_json) in

          if validatePort(port_val) && validateVersion(version) && listLength(features) > 0
          then {
            app_name: app_name,
            version: version,
            port: port_val,
            features: features
          }
          else {
            app_name: "DefaultApp",
            version: "1.0.0",
            port: 8080,
            features: []
          }
        },
        _ => {
          app_name: "DefaultApp",
          version: "1.0.0",
          port: 8080,
          features: []
        }
      }
    },
    Err(_) => {
      app_name: "DefaultApp",
      version: "1.0.0",
      port: 8080,
      features: []
    }
  }

export func main() -> () ! {IO, FS} =
  let configJson = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}" in
  let _ = writeFile("app_config.json", configJson) in
  let config = loadConfig("app_config.json") in
  let numFeatures = listLength(config.features) in
  println("Loaded " ++ config.app_name ++ " v" ++ config.version ++ " on port " ++ show(config.port) ++ " with " ++ show(numFeatures) ++ " features")

module benchmark/solution

import std/io (readFile, writeFile, println)
import std/json (encode, jo, kv, js, jnum, ja)
import std/string (split, contains)
import std/convert (intFromString)

-- Define Option type (if not implicitly available in prelude)
type Option[a] = Some(a) | None

-- Helper to parse age from string
-- Returns Some(positive_int) or None
export func parseAge(s: string) -> Option[int] {
  match intFromString(s) {
    Some(n) if n > 0 => Some(n),
    _ => None -- Covers None from intFromString or non-positive integer
  }
}

-- Helper to validate email
-- Checks if the email string contains "@"
export func validateEmail(email: string) -> bool {
  contains(email, "@")
}

-- Recursive helper to filter elements from a list based on a predicate
func filter[a](pred: func(a) -> bool, xs: List[a]) -> List[a] {
  match xs {
    [] => [],
    ::(x, rest) =>
      if pred(x)
      then ::(x, filter(pred, rest))
      else filter(pred, rest)
  }
}

-- Recursive helper to reverse a list (using an accumulator for efficiency)
func reverse[a](xs: List[a]) -> List[a] {
  letrec rev_acc = \list. \acc.
    match list {
      [] => acc,
      ::(h, t) => rev_acc(t)(::(h, acc))
    } in
  rev_acc(xs)([])
}

-- Recursive helper to get the length of a list
func length[a](xs: List[a]) -> int {
  match xs {
    [] => 0,
    ::(_, rest) => 1 + length(rest)
  }
}

-- Recursive function to process data lines, validate, and convert to JSON objects
-- Returns a list of valid JSON objects (std/json.JsonValue)
func processDataLines(
  lines: List[string],
  validUsersAcc: List[JsonValue]
) -> List[JsonValue] {
  match lines {
    [] => validUsersAcc,
    ::(line, rest) =>
      let parts = split(line, ",") in
      match parts {
        -- Expecting exactly 3 parts: name, ageStr, email
        ::(name, ::(ageStr, ::(email, []))) =>
          let ageOpt = parseAge(ageStr) in
          if validateEmail(email)
          then match ageOpt {
            Some(age) =>
              let userJson = jo([
                kv("name", js(name)),
                kv("age", jnum(intToFloat(age))), -- JSON numbers are floats in std/json
                kv("email", js(email))
              ]) in
              -- Prepend to accumulator, will reverse at the end
              processDataLines(rest, ::(userJson, validUsersAcc))
            None =>
              -- Invalid age (e.g., "notanumber" or <= 0)
              processDataLines(rest, validUsersAcc)
          }
          else
            -- Invalid email (e.g., "noatsymbol.com")
            processDataLines(rest, validUsersAcc)
        _ =>
          -- Malformed line (e.g., not 3 comma-separated parts)
          processDataLines(rest, validUsersAcc)
      }
  }
}

-- Main entry point of the program
export func main() -> () ! {IO, FS} {
  -- 1. Create input CSV file "users.csv"
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com" in
  let _ = writeFile("users.csv", csvContent);

  -- 2. Parse the CSV file
  let fileContent = readFile("users.csv");
  -- Split by newline, then filter out any empty strings that might result from trailing newlines
  let allLines = split(fileContent, "\n");
  let nonEmptyLines = filter(\s. s != "", allLines);

  match nonEmptyLines {
    [] => println("Error: CSV file is empty or contains no data lines."),
    ::(headerLine, dataLines) =>
      -- Headers are 'name,age,email' - we assume this structure and don't need to parse `headerLine` further for this task.
      -- The `processDataLines` function processes data based on this expected structure.

      -- Process data lines, accumulating valid users. The result will be in reverse order.
      let reversedValidUsers = processDataLines(dataLines, []);
      -- Reverse the list to maintain the original order of valid rows from the CSV.
      let validUsers = reverse(reversedValidUsers);

      -- 3. Convert to JSON array
      let jsonArray = ja(validUsers);
      let jsonString = encode(jsonArray);

      -- 4. Write JSON to "users.json" file
      let _ = writeFile("users.json", jsonString);

      -- 5. Print to stdout the confirmation message
      println("Converted " ++ show(length(validUsers)) ++ " valid rows to users.json")
  }
}

