from typing import Generic, TypeVar, Union

_T = TypeVar("_T")
_E = TypeVar("_E")


class Ok(Generic[_T]):
    """Represents a successful result with a value."""

    def __init__(self, value: _T) -> None:
        self._value = value

    @property
    def value(self) -> _T:
        return self._value

    def __repr__(self) -> str:
        return f"Ok({self._value!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Ok):
            return NotImplemented
        return self._value == other._value


class Err(Generic[_E]):
    """Represents a failed result with an error message."""

    def __init__(self, error: _E) -> None:
        self._error = error

    @property
    def error(self) -> _E:
        return self._error

    def __repr__(self) -> str:
        return f"Err({self._error!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Err):
            return NotImplemented
        return self._error == other._error


# Define the Result type as a Union of Ok and Err
# The task specifically asks for `Result[int]` for parse_int,
# implying the error type is implicitly known or fixed for common use.
# For full type safety, a generic Result[ValueType, ErrorType] is better.
# We'll use Result[ValueType, ErrorType] for functions and then
# refine the main type alias for clarity if needed, but Union[Ok[_T], Err[_E]] is correct.
Result = Union[Ok[_T], Err[_E]]


def parse_int(s: str) -> Result[int, str]:
    """
    Parses a string into an integer.

    Returns Ok(n) if the string can be parsed as an integer.
    Returns Err("Invalid integer") otherwise.
    """
    try:
        n = int(s)
        return Ok(n)
    except ValueError:
        return Err("Invalid integer")


def divide_safe(a: int, b: int) -> Result[int, str]:
    """
    Divides two integers safely, returning an integer result (floor division).

    Returns Ok(a//b) if b is not zero.
    Returns Err("Division by zero") if b is zero.
    """
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)


def main() -> None:
    """Runs the test cases for the Result type operations."""

    # Test case 1: parse_int("10") then divide by 2 -> "Result: 5"
    # parse_int("10") -> Ok(10)
    # divide_safe(10, 2) -> Ok(5)
    parse_result_1 = parse_int("10")
    if isinstance(parse_result_1, Ok):
        divide_result_1 = divide_safe(parse_result_1.value, 2)
        if isinstance(divide_result_1, Ok):
            print(f"Result: {divide_result_1.value}")
        else:
            print(f"Error: {divide_result_1.error}")
    else:
        print(f"Error: {parse_result_1.error}")

    # Test case 2: parse_int("10") then divide by 0 -> "Error: Division by zero"
    # parse_int("10") -> Ok(10)
    # divide_safe(10, 0) -> Err("Division by zero")
    parse_result_2 = parse_int("10")
    if isinstance(parse_result_2, Ok):
        divide_result_2 = divide_safe(parse_result_2.value, 0)
        if isinstance(divide_result_2, Ok):
            print(f"Result: {divide_result_2.value}")
        else:
            print(f"Error: {divide_result_2.error}")
    else:
        print(f"Error: {parse_result_2.error}")

    # Test case 3: parse_int("abc") -> "Error: Invalid integer"
    # parse_int("abc") -> Err("Invalid integer")
    parse_result_3 = parse_int("abc")
    if isinstance(parse_result_3, Ok):
        # This branch would not be reached for "abc"
        # If it were, we'd proceed to division, e.g., divide_safe(parse_result_3.value, 2)
        print(f"Result: {parse_result_3.value}") # This line won't be hit
    else:
        print(f"Error: {parse_result_3.error}")


if __name__ == "__main__":
    main()

