from __future__ import annotations

import argparse
import csv
import json
import logging
import re
import sys
from dataclasses import dataclass, asdict
from fnmatch import fnmatch
from pathlib import Path
from typing import Iterable, Iterator, Sequence


@dataclass(frozen=True)
class FileStats:
    path: Path
    lines: int
    words: int
    characters: int
    bytes: int


WORD_PATTERN = re.compile(r"\S+")


def parse_args(argv: Sequence[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Analyze text files and report line, word, character, and byte counts."
    )
    parser.add_argument(
        "path",
        nargs="?",
        default=".",
        help="Root path to scan (default: current directory).",
    )
    parser.add_argument(
        "-I",
        "--include",
        action="append",
        default=None,
        help="Glob pattern to include (can be used multiple times). Default: *.txt, *.md, *.py",
    )
    parser.add_argument(
        "-E",
        "--exclude",
        action="append",
        default=None,
        help="Glob pattern to exclude (can be used multiple times).",
    )
    parser.add_argument(
        "-r",
        "--recursive",
        action="store_true",
        help="Recurse into subdirectories.",
    )
    parser.add_argument(
        "-o",
        "--output",
        choices=("table", "json", "csv"),
        default="table",
        help="Output format (default: table).",
    )
    parser.add_argument(
        "--summary-only",
        action="store_true",
        help="Only output totals summary, not per-file details.",
    )
    parser.add_argument(
        "--encoding",
        default="utf-8",
        help="File encoding to use when reading (default: utf-8).",
    )
    parser.add_argument(
        "--follow-symlinks",
        action="store_true",
        help="Follow symbolic links during traversal.",
    )
    parser.add_argument(
        "-v",
        "--verbose",
        action="count",
        default=0,
        help="Increase verbosity (-v for INFO, -vv for DEBUG).",
    )
    parser.add_argument(
        "-q",
        "--quiet",
        action="store_true",
        help="Suppress non-critical warnings.",
    )
    parser.add_argument(
        "--max-files",
        type=int,
        default=None,
        help="Limit the number of files processed.",
    )
    return parser.parse_args(argv)


def configure_logging(verbose: int, quiet: bool) -> None:
    level = logging.WARNING
    if quiet:
        level = logging.ERROR
    elif verbose >= 2:
        level = logging.DEBUG
    elif verbose == 1:
        level = logging.INFO

    logging.basicConfig(
        level=level,
        format="%(levelname)s: %(message)s",
    )


def normalize_patterns(patterns: Sequence[str] | None, default: Sequence[str] | None = None) -> list[str]:
    if patterns is None:
        return list(default or [])
    return [p for pat in patterns for p in pat.split(",") if p.strip()]


def iter_files(
    root: Path,
    recursive: bool,
    includes: Sequence[str],
    excludes: Sequence[str],
    follow_symlinks: bool,
) -> Iterator[Path]:
    if not root.exists():
        raise FileNotFoundError(f"Path does not exist: {root}")
    if root.is_file():
        if path_matches(root, includes, excludes):
            yield root
        return

    def should_enter_dir(d: Path) -> bool:
        # Avoid infinite loops with symlinks if not allowed
        if d.is_symlink() and not follow_symlinks:
            logging.debug("Skipping symlinked directory: %s", d)
            return False
        return True

    if recursive:
        for entry in root.rglob("*"):
            try:
                if entry.is_dir():
                    if not should_enter_dir(entry):
                        continue
                    # rglob already recurses; nothing to do for directories here
                    continue
                if entry.is_symlink() and not follow_symlinks:
                    logging.debug("Skipping symlinked file: %s", entry)
                    continue
                if entry.is_file() and path_matches(entry, includes, excludes):
                    yield entry
            except OSError as exc:
                logging.warning("Skipping %s due to error: %s", entry, exc)
    else:
        for entry in root.iterdir():
            try:
                if entry.is_dir():
                    continue
                if entry.is_symlink() and not follow_symlinks:
                    logging.debug("Skipping symlinked file: %s", entry)
                    continue
                if entry.is_file() and path_matches(entry, includes, excludes):
                    yield entry
            except OSError as exc:
                logging.warning("Skipping %s due to error: %s", entry, exc)


def path_matches(path: Path, includes: Sequence[str], excludes: Sequence[str]) -> bool:
    name = path.name
    if includes:
        if not any(fnmatch(name, pat) for pat in includes):
            return False
    if excludes:
        if any(fnmatch(name, pat) for pat in excludes):
            return False
    return True


def collect_file_stats(path: Path, encoding: str) -> FileStats:
    try:
        with path.open("r", encoding=encoding, errors="ignore") as fh:
            text = fh.read()
    except OSError as exc:
        raise IOError(f"Failed to read file {path}: {exc}") from exc

    lines = text.count("\n")
    # Account for last line without newline
    if text and not text.endswith("\n"):
        lines += 1

    words = len(WORD_PATTERN.findall(text))
    characters = len(text)
    try:
        size_bytes = path.stat().st_size
    except OSError:
        size_bytes = len(text.encode(encoding, errors="ignore"))

    return FileStats(path=path, lines=lines, words=words, characters=characters, bytes=size_bytes)


def aggregate_totals(stats: Iterable<FileStats]) -> FileStats:
    total_lines = 0
    total_words = 0
    total_chars = 0
    total_bytes = 0
    last_path = Path("-")
    for s in stats:
        total_lines += s.lines
        total_words += s.words
        total_chars += s.characters
        total_bytes += s.bytes
        last_path = s.path
    return FileStats(path=last_path, lines=total_lines, words=total_words, characters=total_chars, bytes=total_bytes)


def output_table(stats: list[FileStats], summary_only: bool) -> None:
    rows = []
    if not summary_only:
        rows.extend(
            [
                [
                    str(s.path),
                    str(s.lines),
                    str(s.words),
                    str(s.characters),
                    str(s.bytes),
                ]
                for s in stats
            ]
        )
    totals = aggregate_totals(stats)
    total_row = ["TOTAL", str(totals.lines), str(totals.words), str(totals.characters), str(totals.bytes)]
    headers = ["Path", "Lines", "Words", "Chars", "Bytes"]

    all_rows = ([headers] + rows + [total_row]) if not summary_only else ([headers] + [total_row])
    col_widths = [max(len(row[i]) for row in all_rows) for i in range(len(headers))]

    def fmt_row(row: list[str]) -> str:
        return "  ".join(val.ljust(col_widths[i]) for i, val in enumerate(row))

    for i, row in enumerate(all_rows):
        print(fmt_row(row))
        if i == 0:
            print(fmt_row(["-" * w for w in col_widths]))


def output_json(stats: list[FileStats], summary_only: bool) -> None:
    if summary_only:
        totals = aggregate_totals(stats)
        data = {"summary": asdict(totals)}
    else:
        data = {
            "files": [asdict(s) for s in stats],
            "summary": asdict(aggregate_totals(stats)),
        }
    json.dump(data, sys.stdout, indent=2)
    sys.stdout.write("\n")
    sys.stdout.flush()


def output_csv(stats: list[FileStats], summary_only: bool) -> None:
    writer = csv.writer(sys.stdout)
    writer.writerow(["Path", "Lines", "Words", "Chars", "Bytes"])
    if not summary_only:
        for s in stats:
            writer.writerow([str(s.path), s.lines, s.words, s.characters, s.bytes])
    totals = aggregate_totals(stats)
    writer.writerow(["TOTAL", totals.lines, totals.words, totals.characters, totals.bytes])


def run(argv: Sequence[str]) -> int:
    args = parse_args(argv)
    configure_logging(args.verbose, args.quiet)

    root = Path(args.path).resolve()
    includes = normalize_patterns(args.include, default=["*.txt", "*.md", "*.py"])
    excludes = normalize_patterns(args.exclude, default=[])

    logging.debug("Root: %s", root)
    logging.debug("Includes: %s", includes)
    logging.debug("Excludes: %s", excludes)
    logging.debug("Recursive: %s", args.recursive)

    try:
        files_iter = iter_files(
            root=root,
            recursive=args.recursive,
            includes=includes,
            excludes=excludes,
            follow_symlinks=args.follow_symlinks,
        )
    except FileNotFoundError as exc:
        logging.error(str(exc))
        return 2

    stats: list[FileStats] = []
    count = 0
    for path in files_iter:
        if args.max_files is not None and count >= args.max_files:
            logging.info("Reached max files limit: %d", args.max_files)
            break
        try:
            stat = collect_file_stats(path, args.encoding)
            stats.append(stat)
            count += 1
            logging.debug("Processed %s: %s lines, %s words, %s chars, %s bytes", path, stat.lines, stat.words, stat.characters, stat.bytes)
        except IOError as exc:
            logging.warning("%s", exc)
            continue

    if not stats:
        logging.warning("No files matched the given patterns.")
        # Still produce an empty report with zero totals
        stats = []

    if args.output == "table":
        output_table(stats, args.summary_only)
    elif args.output == "json":
        output_json(stats, args.summary_only)
    else:
        output_csv(stats, args.summary_only)

    return 0


def main() -> None:
    sys.exit(run(sys.argv[1:]))


if __name__ == "__main__":
    main()

