export func filter[a](pred: func(a) -> bool, xs: [a]) -> [a] {
  match xs {
    [] => [],
    Cons(x, rest) =>
      if pred(x)
      then Cons(x, filter(pred, rest))
      else filter(pred, rest)
  }
}

export func foldl[a, b](f: func(b, a) -> b, acc: b, xs: [a]) -> b {
  match xs {
    [] => acc,
    Cons(x, rest) => foldl(f, f(acc, x), rest)
  }
}

