    timer: int

class Tick:
    pass

class Reset:
    pass

StateType = Union[Green, Yellow, Red]
EventType = Union[Tick, Reset]

def transition(state: StateType, event: EventType) -> StateType:
    if isinstance(event, Tick):
        if isinstance(state, Green):
            if state.timer > 0:
                return Green(state.timer - 1)
            else:
                return Yellow(3)
        elif isinstance(state, Yellow):
            if state.timer > 0:
                return Yellow(state.timer - 1)
            else:
                return Red(10)
        elif isinstance(state, Red):
            if state.timer > 0:
                return Red(state.timer - 1)
            else:
                return Green(20)
    elif isinstance(event, Reset):
        return Green(20)
    # This point should theoretically be unreachable with exhaustive type checking
    # and properly constructed inputs based on the ADT definitions.
    # In a production system, one might raise an error here for robustness.
    # For this specific task's ADT-like exhaustive matching, all defined cases are covered.
    raise ValueError(f"Unhandled state-event combination: {state}, {event}")


def show_state(state: StateType) -> str:
    if isinstance(state, Green):
        return f"GREEN ({state.timer}sec)"
    elif isinstance(state, Yellow):
        return f"YELLOW ({state.timer}sec)"
    elif isinstance(state, Red):
        return f"RED ({state.timer}sec)"
    # This point should theoretically be unreachable with exhaustive type checking
    # and properly constructed inputs.
    raise ValueError(f"Unknown state type: {state}")


