    Leaf(v) => fn(acc)(v),
    Node(left, v, right) =>
      let accLeft = foldTree(fn, acc, left);
      let accV = fn(accLeft)(v);
      foldTree(fn, accV, right)
  }
}

export func concatLists(a: [int], b: [int]) -> [int] {
  match a {
    [] => b,
    Cons(h, t) => Cons(h, concatLists(t, b))
  }
}

export func treeToList(tree: Tree) -> [int] {
  match tree {
    Leaf(v) => [v],
    Node(left, v, right) =>
      let leftList = treeToList(left);
      let rightList = treeToList(right);
      concatLists(leftList, Cons(v, rightList))
  }
}

