from dataclasses import dataclass
from typing import List, Callable

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Leaf | Node

def map_tree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """
    Recursively applies a function to all integer values in the tree.
    Returns a new tree with transformed values.
    """
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:  # isinstance(tree, Node)
        return Node(
            map_tree(fn, tree.left),
            fn(tree.value),
            map_tree(fn, tree.right)
        )

def fold_tree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """
    Performs an in-order fold over the tree values.
    Combines all values using the given function and an initial accumulator.
    """
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:  # isinstance(tree, Node)
        acc_left = fold_tree(fn, acc, tree.left)
        acc_val = fn(acc_left, tree.value)
        return fold_tree(fn, acc_val, tree.right)

def tree_to_list(tree: Tree) -> List[int]:
    """
    Performs an in-order traversal of the tree and returns a list of its values.
    Includes all values, including dummy 0s, for structural representation.
    """
    if isinstance(tree, Leaf):
        return [tree.value]
    else:  # isinstance(tree, Node)
        return tree_to_list(tree.left) + [tree.value] + tree_to_list(tree.right)

def tree_depth(tree: Tree) -> int:
    """
    Calculates the maximum depth of the tree.
    A Leaf node has a depth of 1.
    """
    if isinstance(tree, Leaf):
        return 1
    else:  # isinstance(tree, Node)
        return 1 + max(tree_depth(tree.left), tree_depth(tree.right))

def main():
    """
    Main function to demonstrate tree transformations and operations.
    """
    # Build the example tree as specified:
    #         5
    #        / \
    #       3   8
    #      /   / \
    #     1   7   9
    # Note: Leaf(0) is used as a dummy for a missing child in the Node(Leaf(1), 3, Leaf(0)) structure.
    example_tree: Tree = Node(
        Node(Leaf(1), 3, Leaf(0)),
        5,
        Node(Leaf(7), 8, Leaf(9))
    )

    # 1. Original values: Print in-order values [1, 3, 5, 7, 8, 9]
    # Filter out the dummy 0s for display purposes.
    original_values_raw = tree_to_list(example_tree)
    original_filtered = [x for x in original_values_raw if x != 0]
    print(f"Original: {original_filtered}")

    # 2. Doubled values: Map with lambda x: x * 2, print [2, 6, 10, 14, 16, 18]
    doubled_tree = map_tree(lambda x: x * 2, example_tree)
    doubled_values_raw = tree_to_list(doubled_tree)
    doubled_filtered = [x for x in doubled_values_raw if x != 0]
    print(f"Doubled: {doubled_filtered}")

    # 3. Sum of values: Fold with lambda a, b: a + b starting with 0, print sum (33)
    # The fold operation includes all values in the ADT, including the dummy 0.
    # The sum 1 + 3 + 0 + 5 + 7 + 8 + 9 correctly results in 33.
    total_sum = fold_tree(lambda a, b: a + b, 0, example_tree)
    print(f"Sum: {total_sum}")

    # 4. Depth: Calculate tree depth (3)
    depth = tree_depth(example_tree)
    print(f"Depth: {depth}")

if __name__ == "__main__":
    main()

